import json

import pytest

from open_weight_lingua import span_knockout_confirm as scf
from open_weight_lingua import tasks
from open_weight_lingua.splits import SPLIT_ORDER, build_plan


def _tiny_plan():
    from test_pilot_stages import TINY_COUNTS

    return build_plan(TINY_COUNTS)


@pytest.fixture
def test_split(monkeypatch):
    """A test-only split name and seed: the real fresh programs are first generated by the frozen run."""
    monkeypatch.setitem(tasks.SPLIT_SEEDS, "test_fresh", 999001)
    monkeypatch.setattr(scf, "SPLIT", "test_fresh")


def test_the_fresh_seed_is_registered_and_new():
    assert tasks.SPLIT_SEEDS["fresh_2026_10"] == 206001
    assert tasks.SPLIT_SEEDS["fresh_2026_10"] not in {tasks.SPLIT_SEEDS[name] for name in SPLIT_ORDER}


def test_fresh_groups_exclude_every_phase_two_program(monkeypatch, test_split):
    plan = _tiny_plan()
    monkeypatch.setattr(scf, "PLAN_HASH", plan.plan_hash)
    groups, stats = scf.fresh_groups(plan, count=6)
    old = {tasks.canonical(p) for name in SPLIT_ORDER for g in plan.groups[name] for p in (g.source, g.counterfactual)}
    new = {tasks.canonical(p) for g in groups for p in (g.source, g.counterfactual)}
    assert len(groups) == 6 and not new & old and stats["inventory_sha256"]
    assert all(g.group_id.startswith("test_fresh-") for g in groups)


def test_a_different_plan_is_refused(test_split):
    with pytest.raises(ValueError, match="frozen Phase Two plan"):
        scf.fresh_groups(_tiny_plan(), count=2)


def _fake_run(tmp_path, family, correct, groups=100, inventory="inv"):
    run = tmp_path / family
    run.mkdir()
    stimuli, results = [], []
    for g in range(groups):
        for k in range(4):
            sid = f"fresh_2026_10-{g:04d}-{'AB'[k // 2]}-{'xy'[k % 2]}"
            stimuli.append({"id": sid, "group_id": f"fresh_2026_10-{g:04d}", "last_line_assigns_asked": k % 2 == 0,
                            "asked_last_update_kind": "literal", "asked_copies_other": False})
            results.append({"id": sid, **{c: {"correct": f(g, k), "logprob": 0.0} for c, f in correct.items()}})
    (run / "stimuli.json").write_text(json.dumps(stimuli))
    (run / "results.jsonl").write_text("".join(json.dumps(r) + "\n" for r in results))
    (run / "manifest.json").write_text(json.dumps({"family": family, "prompts": len(results), "plan_hash": scf.PLAN_HASH,
                                                   "protocol_sha256": scf.sha256_file(scf.PROTOCOL),
                                                   "stimuli_sha256": scf.sha256_file(run / "stimuli.json"),
                                                   "generation": {"inventory_sha256": inventory}}))
    (run / "completion.json").write_text(json.dumps({"status": "COMPLETE"}))
    return run


def test_verdicts_follow_the_frozen_rules_including_the_last_writer_subset(tmp_path, monkeypatch):
    monkeypatch.setattr(scf, "RESAMPLES", 2000)
    always, never = (lambda g, k: True), (lambda g, k: False)
    # last_token fails only where the last line assigns the asked variable (k even): the subset claim still survives.
    pattern = {"baseline": always, "asked_lines_minus_last": never, "other_lines_minus_last": always,
               "last_token": lambda g, k: k % 2 == 1}
    gemma = _fake_run(tmp_path, "gemma3-12b", pattern)
    qwen = _fake_run(tmp_path, "qwen2.5-7b", {**pattern, "other_lines_minus_last": lambda g, k: k != 3})
    result = scf.evaluate([gemma, qwen])
    status = {h["id"]: h["status"] for h in result["hypotheses"]}
    assert status == {"G1": "SUPPORTED", "G2": "SUPPORTED", "G3": "SUPPORTED",
                      "Q1": "SUPPORTED", "Q2": "NOT_SUPPORTED", "Q3": "SUPPORTED"}
    by_id = {h["id"]: h for h in result["hypotheses"]}
    assert by_id["G3"]["prompts"] == 200 and by_id["G3"]["mean_loss"] == 0.0
    assert by_id["Q2"]["mean_loss"] == pytest.approx(0.25)


def test_families_must_share_the_same_fresh_programs(tmp_path):
    ok = {c: (lambda g, k: True) for c in ("baseline", *scf.CONDITIONS)}
    a = _fake_run(tmp_path, "gemma3-12b", ok, inventory="one")
    b = _fake_run(tmp_path, "qwen2.5-7b", ok, inventory="two")
    with pytest.raises(ValueError, match="different fresh programs"):
        scf.evaluate([a, b])


def test_run_end_to_end_on_a_fixture_model(tmp_path, monkeypatch, model_factory, tokenizer, test_split):
    """Tiny random model and fixture tokens; plumbing only, never a real result."""
    import transformers

    from test_answer_knockout import _eager

    plan = _tiny_plan()
    lock = tmp_path / "model-lock-gemma3-12b.json"
    lock.write_text(json.dumps({"models": {"target": {"revision": "r", "files": {}}}}))
    monkeypatch.setattr(scf, "PLAN_HASH", plan.plan_hash)
    monkeypatch.setattr(scf, "build_plan", lambda: plan)
    monkeypatch.setattr(scf, "GROUPS", 3)
    monkeypatch.setattr(scf, "fresh_groups", lambda p, count=3, real=scf.fresh_groups: real(p, count))
    monkeypatch.setattr(scf, "ROUTES", {"gemma3-12b": ("after_program", 1)})
    monkeypatch.setattr(scf, "program_span", lambda tok, ids, body: (0, 1))
    monkeypatch.setattr(scf, "token_lines", lambda tok, ids, span, body: [0, 1])
    monkeypatch.setattr(scf, "load_model", lambda path, role, device: _eager(model_factory(layers=3)))
    monkeypatch.setattr(scf, "read_lock", lambda path: json.loads(path.read_text()))
    monkeypatch.setattr(scf, "model_paths", lambda lock, cache: {"target": tmp_path})
    monkeypatch.setattr(scf, "verify_models", lambda lock, paths: {})
    monkeypatch.setattr(scf, "compatibility", lambda device: {})
    monkeypatch.setattr(transformers.AutoTokenizer, "from_pretrained", lambda path, **kwargs: tokenizer)
    run_dir = tmp_path / "confirm"
    scf.main(["run", "--lock", str(lock), "--device", "cpu", "--run-dir", str(run_dir)])
    completion = json.loads((run_dir / "completion.json").read_text())
    manifest = json.loads((run_dir / "manifest.json").read_text())
    assert completion["status"] == "COMPLETE" and completion["rows_written"] == manifest["prompts"] == 12
    assert manifest["generation"]["inventory_sha256"] and manifest["split"] == "test_fresh"
    first = json.loads((run_dir / "results.jsonl").read_text().splitlines()[0])
    assert set(first) == {"id", "baseline", *scf.CONDITIONS}
